import org.jetbrains.kotlin.gradle.dsl.JvmTarget

plugins {
    alias(libs.plugins.jetbrainsKotlinJvm)
    alias(libs.plugins.serialization)
    // Only for jsoniter-scala, whose codec is generated by a Scala 3 macro: the one Scala
    // file in src/main/scala. Kotlin and Scala never reference each other at compile time;
    // the Kotlin side loads the Scala class by name through JDK functional interfaces.
    scala
    application
}

application {
    mainClass.set("com.vitorpamplona.jsonbench.MainKt")
    applicationName = "jsonbench"
    // The parent process forks one child JVM per parser with these same arguments
    // (see Main.kt), so every parser gets the same fixed heap and collector.
    // - A fixed 2g heap: no heap resizing in the middle of a measurement.
    // - G1 explicitly: the JVM falls back to Serial on small containers, and the
    //   collector changes both the allocation cost and the GC numbers we report.
    // - jdk.incubator.vector: simdjson-java needs the incubating Vector API.
    applicationDefaultJvmArgs =
        listOf(
            "-Xms2g",
            "-Xmx2g",
            "-XX:+UseG1GC",
            "--add-modules",
            "jdk.incubator.vector",
            "-Dfile.encoding=UTF-8",
        )
}

kotlin {
    jvmToolchain(21)
    compilerOptions {
        jvmTarget.set(JvmTarget.JVM_21)
    }
}

// Library versions the harness reports in every result row, taken from the same
// catalog entries the dependencies below resolve.
val generatedResources = layout.buildDirectory.dir("generated/jsonbench-resources")
val writeLibraryVersions by tasks.registering(WriteProperties::class) {
    destinationFile.set(generatedResources.map { it.file("jsonbench-versions.properties") })
    property("jackson", libs.versions.jackson.get())
    property("kotlinx-serialization", libs.versions.kotlinxSerialization.get())
    property("gson", libs.versions.jsonBenchGson.get())
    property("moshi", libs.versions.jsonBenchMoshi.get())
    property("fastjson2", libs.versions.jsonBenchFastjson2.get())
    property("dsl-json", libs.versions.jsonBenchDslJson.get())
    property("simdjson-java", libs.versions.jsonBenchSimdjson.get())
    property("org.json", libs.versions.jsonBenchOrgJson.get())
    property("jsoniter", libs.versions.jsonBenchJsoniter.get())
    property("parsson", libs.versions.jsonBenchParsson.get())
    property("minimal-json", libs.versions.jsonBenchMinimalJson.get())
    property("json-smart", libs.versions.jsonBenchJsonSmart.get())
    property("jsoniter-scala", libs.versions.jsonBenchJsoniterScala.get())
    property("app", libs.versions.app.get())
}
sourceSets.main {
    resources.srcDir(writeLibraryVersions.map { generatedResources.get() })
}

dependencies {
    // The production path under test: JacksonMapper / KotlinSerializationMapper.
    // Quartz exposes jackson-databind as `api`, which the plain Jackson parsers use too.
    implementation(project(":quartz"))
    implementation(libs.kotlinx.serialization.json)

    // Competing parsers (jsonBench-only catalog block).
    implementation(libs.jsonbench.gson)
    implementation(libs.jsonbench.moshi)
    implementation(libs.jsonbench.fastjson2)
    implementation(libs.jsonbench.dsljson)
    implementation(libs.jsonbench.simdjson)
    implementation(libs.jsonbench.orgjson)
    implementation(libs.jsonbench.jsoniter)
    implementation(libs.jsonbench.parsson)
    implementation(libs.jsonbench.minimaljson)
    implementation(libs.jsonbench.jsonsmart)
    implementation(libs.jsonbench.scala3.library)
    implementation(libs.jsonbench.jsoniter.scala.core)
    compileOnly(libs.jsonbench.jsoniter.scala.macros)

    // JNI secp256k1 backend quartz needs at runtime on plain JVM.
    runtimeOnly(libs.secp256k1.kmp.jni.jvm)
}
